from typing import List


def solution(arr: List[str]) -> int:
    n = len(arr)
    S = "".join(arr)
    T = len(S)
    P = [0] * (n + 1)              # P[j]：第 j 条分界线的原始位置
    for i, s in enumerate(arr):
        P[i + 1] = P[i] + len(s)

    def raw(j):                    # 第 j 条分界线可移动到的位置
        return {P[j]} if j in (0, n) else {P[j] - 1, P[j], P[j] + 1}

    def cand(j):                   # 还要满足镜像约束 p_j + p_{n-j} = T
        mirror = raw(n - j)
        return {p for p in raw(j) if T - p in mirror}

    half = n // 2                  # 只需决定分界线 0..half
    states = cand(0)               # = {0}
    for i in range(half):          # 检查第 i 段与第 n-1-i 段
        if n % 2 == 1 or i + 1 < half:
            nxt_cand = cand(i + 1)
        else:                      # n 为偶数时中间分界线必须正好在 T/2
            nxt_cand = {T // 2} & cand(i + 1) if T % 2 == 0 else set()
        nxt = set()
        for p in states:
            for q in nxt_cand:
                if q >= p and S[p:q] == S[T - q:T - p]:
                    nxt.add(q)
        states = nxt
        if not states:
            return 0
    return 1


if __name__ == "__main__":
    print(solution(["aa", "bab", "cde", "aba", "ab"]))
    print(solution(["palindrome"]))
    print(solution(["aaaaaa", "aa"]))
